WITH params AS (SELECT date('now','+3 hours') AS cairoDay), legacy AS ( SELECT l.line_id AS lineId,l.order_id AS orderId, COALESCE(lr.status,l.status,'') AS lineStatus, COALESCE(l.department,'') AS dept, COALESCE(l.expected_delivery_at,'') AS dueAt, COALESCE(l.fly_print,0) AS flyFlag, 0 AS originRank FROM employee_core_lines_v1 l JOIN employee_core_orders_v1 o ON o.order_id=l.order_id LEFT JOIN t12_legacy_line_runtime lr ON lr.line_id=l.line_id AND lr.order_id=l.order_id LEFT JOIN employee_core_archive_lines_v1 a ON a.line_id=l.line_id WHERE l.active=1 AND o.active=1 AND a.line_id IS NULL ), native AS ( SELECT l.line_id AS lineId,l.order_id AS orderId, COALESCE(r.status,l.status,'') AS lineStatus, COALESCE(l.department,'') AS dept, COALESCE(s.expected_delivery_date,'') AS dueAt, COALESCE(l.fly_print,0) AS flyFlag, 1 AS originRank FROM t12_prod_lines l JOIN t12_prod_orders o ON o.order_id=l.order_id LEFT JOIN t12_prod_line_runtime r ON r.line_id=l.line_id LEFT JOIN t12_prod_order_schedule s ON s.order_id=o.order_id LEFT JOIN employee_core_archive_lines_v1 a ON a.line_id=l.line_id WHERE a.line_id IS NULL ), combined AS ( SELECT * FROM legacy UNION ALL SELECT * FROM native ), ranked AS ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY lineId ORDER BY originRank DESC,dueAt DESC,lineStatus DESC,orderId DESC ) AS rn FROM combined ), reconciled AS ( SELECT trim(dept) AS department, CASE WHEN trim(COALESCE(dueAt,''))='' THEN 'DUE_FIELD_MISSING_REVIEW' WHEN CAST(flyFlag AS INTEGER)=1 THEN 'FLY_PRINT_1_EXCLUDED' ELSE 'IN_AP112_CAIRO_TRIAGE' END AS coverageBucket FROM ranked WHERE rn=1 AND trim(lineStatus)='طلب جديد' AND trim(dept) IN ('طباعة','ليزر') ) SELECT department,coverageBucket,COUNT(*) AS lineCount FROM reconciled GROUP BY department,coverageBucket ORDER BY department,coverageBucket;
